-- create "challenge_exercises" table
CREATE TABLE "challenge_exercises" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "position" bigint NOT NULL, "linked_at" timestamptz NOT NULL, "challenge_id" uuid NOT NULL, "exercise_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "challenge_exercises_challenges_challenge" FOREIGN KEY ("challenge_id") REFERENCES "challenges" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "challenge_exercises_exercises_exercise" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "challengeexercise_challenge_id_exercise_id" to table: "challenge_exercises"
CREATE UNIQUE INDEX "challengeexercise_challenge_id_exercise_id" ON "challenge_exercises" ("challenge_id", "exercise_id");
-- create index "challengeexercise_challenge_id_position" to table: "challenge_exercises"
CREATE INDEX "challengeexercise_challenge_id_position" ON "challenge_exercises" ("challenge_id", "position");
-- create "content_node_exercises" table
CREATE TABLE "content_node_exercises" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "position" bigint NOT NULL, "linked_at" timestamptz NOT NULL, "content_node_id" uuid NOT NULL, "exercise_id" uuid NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "content_node_exercises_content_nodes_content_node" FOREIGN KEY ("content_node_id") REFERENCES "content_nodes" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "content_node_exercises_exercises_exercise" FOREIGN KEY ("exercise_id") REFERENCES "exercises" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- create index "contentnodeexercise_content_node_id_exercise_id" to table: "content_node_exercises"
CREATE UNIQUE INDEX "contentnodeexercise_content_node_id_exercise_id" ON "content_node_exercises" ("content_node_id", "exercise_id");
-- create index "contentnodeexercise_content_node_id_position" to table: "content_node_exercises"
CREATE INDEX "contentnodeexercise_content_node_id_position" ON "content_node_exercises" ("content_node_id", "position");
